// src/lib/mcp/tools/list-services.ts
var list_services_default = defineTool({
  name: "list_services",
  title: "Listar categorias de servi\xE7os",
  description: "Lista as categorias do cat\xE1logo de servi\xE7os da Tikvah com um resumo de cada uma.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const categories = TIKVAH_CATEGORIES.map((category) => ({
      id: category.id,
      title: category.title,
      summary: category.summary,
      itemCount: category.items.length
    }));
    return {
      content: [
        {
          type: "text",
          text: `${TIKVAH_INTRO}

${categories.map((c) => `- ${c.title} (${c.id}): ${c.summary}`).join("\n")}`
        }
      ],
      structuredContent: { categories }
    };
  }
});

// src/lib/mcp/tools/get-service-category.ts
import { ToolError, defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@3.0.1";
import { z } from "npm:zod@^4.6.5";
var get_service_category_default = defineTool2({
  name: "get_service_category",
  title: "Detalhe de uma categoria de servi\xE7os",
  description: "Devolve todos os servi\xE7os de uma categoria do cat\xE1logo Tikvah, a partir do seu id.",
  inputSchema: {
    category_id: z.string().min(1).describe("Id da categoria, por exemplo 'saude-mental'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category_id }) => {
    const category = TIKVAH_CATEGORIES.find((c) => c.id === category_id);
    if (!category) {
      throw new ToolError(
        `Categoria desconhecida: ${category_id}. Ids v\xE1lidos: ${TIKVAH_CATEGORIES.map((c) => c.id).join(", ")}`
      );
    }
    const detail = {
      id: category.id,
      title: category.title,
      summary: category.summary,
      items: category.items.map((item) => ({
        title: item.title,
        description: item.description
      }))
    };
    return {
      content: [
        {
          type: "text",
          text: `${detail.title}
${detail.summary}

${detail.items.map((i) => `- ${i.title}: ${i.description}`).join("\n")}`
        }
      ],
      structuredContent: { category: detail }
    };
  }
});

