// src/lib/mcp/tools/list-appointments.ts
import { defineTool as defineTool4 } from "npm:@lovable.dev/mcp-js@3.0.1";
import { z as z2 } from "npm:zod@^4.6.5";

// src/lib/mcp/supabase.ts
import { createClient } from "npm:@supabase/supabase-js@^2.112.3";
function runtimeEnv(name) {
  const runtime = globalThis;
  return runtime.Deno?.env?.get?.(name) ?? runtime.process?.env?.[name];
}
function configuredEnv(names) {
  for (const name of names) {
    const value = runtimeEnv(name)?.trim();
    if (value) return value;
  }
  return void 0;
}
function supabaseProjectUrl() {
  const url = configuredEnv(["SUPABASE_URL", "VITE_SUPABASE_URL"]);
  if (!url) throw new Error("SUPABASE_URL (or VITE_SUPABASE_URL) is required");
  return url;
}
function supabasePublishableKey() {
  const direct = configuredEnv([
    "SUPABASE_PUBLISHABLE_KEY",
    "VITE_SUPABASE_PUBLISHABLE_KEY"
  ]);
  if (direct) return direct;
  const keyset = runtimeEnv("SUPABASE_PUBLISHABLE_KEYS");
  if (keyset) {
    try {
      const parsed = JSON.parse(keyset);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        const keys = parsed;
        const key = [keys.default, ...Object.values(keys)].find((v) => typeof v === "string" && v.trim().startsWith("sb_publishable_"))?.trim();
        if (key) return key;
      }
    } catch {
    }
  }
  const legacy = configuredEnv(["SUPABASE_ANON_KEY", "VITE_SUPABASE_ANON_KEY"]);
  if (legacy) return legacy;
  throw new Error(
    "SUPABASE_PUBLISHABLE_KEY, SUPABASE_PUBLISHABLE_KEYS, or SUPABASE_ANON_KEY is required"
  );
}
function supabaseForUser(ctx) {
  const token = ctx.getToken();
  if (!token) throw new Error("supabaseForUser requires a verified OAuth token");
  return createClient(supabaseProjectUrl(), supabasePublishableKey(), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
}

// src/lib/mcp/tools/list-appointments.ts
var list_appointments_default = defineTool4({
  name: "list_appointments",
  title: "Listar marca\xE7\xF5es",
  description: "Lista as marca\xE7\xF5es mais recentes a que o utilizador autenticado tem acesso. O acesso \xE9 controlado pelas regras de seguran\xE7a da base de dados.",
  inputSchema: {
    limit: z2.number().int().min(1).max(50).optional().describe("N\xFAmero m\xE1ximo de marca\xE7\xF5es a devolver (por omiss\xE3o 10)."),
    status: z2.string().trim().min(1).optional().describe("Filtrar por estado da marca\xE7\xE3o, por exemplo 'pending'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limit, status }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return {
        content: [{ type: "text", text: "\xC9 necess\xE1rio iniciar sess\xE3o." }],
        isError: true
      };
    }
    const supabase = supabaseForUser(ctx);
    let query = supabase.from("appointments").select("id, client_name, service_type, preferred_date, status, created_at").order("created_at", { ascending: false }).limit(limit ?? 10);
    if (status) query = query.eq("status", status);
    const { data, error } = await query;
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    const appointments = (data ?? []).map((row) => ({
      id: row.id,
      clientName: row.client_name,
      serviceType: row.service_type,
      preferredDate: row.preferred_date,
      status: row.status,
      createdAt: row.created_at
    }));
    return {
      content: [
        {
          type: "text",
          text: appointments.length ? appointments.map((a) => `- ${a.preferredDate} \u2014 ${a.clientName} (${a.serviceType}) [${a.status}]`).join("\n") : "Sem marca\xE7\xF5es acess\xEDveis para esta conta."
        }
      ],
      structuredContent: { appointments }
    };
  }
});

